            if (entry.getValue() > maxCount) {
                maxCount = entry.getValue();
                mostPopularColor = entry.getKey();
            }
        }

        return new Car(mostPopularColor);
    }

    public static void main(String[] args) {
        List<Car> cars = List.of(
            new Car("Red"),
            new Car("Blue"),
            new Car("Red"),
            new Car("Green"),
            new Car("Red")
        );

        Car mostPopularCar = mostPopularCar(cars);
        System.out.println("Most popular car color: " + mostPopularCar.getColor());
        System.out.println("Count: " + mostPopularCar.getColor().split(" ")[0]);
    }
}
```

In this example, the `Car` class is defined to hold the car's color. The `countColors` method counts the occurrences of each car color, and the `mostPopularCar` method finds the car color with the highest count and returns it. The `main` method demonstrates how to use these methods with a sample list of cars.

